/**
 * Which uppercase codepoints does unicode61 leave uppercase — under `remove_diacritics 0`?
 *
 * The set pinned in tokenize.ts was generated by exactly this sweep, but against
 * `remove_diacritics 2`. Changing the tokenizer to 0 changes the answer: with stripping on,
 * `İ` decomposes and its mark is removed, so SQLite stored `i` and the codepoint did not
 * belong in the keep-case set. With stripping off, SQLite keeps `İ` verbatim — and the JS
 * side, which lowercases it into `i` + a combining mark, now disagrees with the index.
 *
 * So this re-runs the generator under the setting the code actually ships, and prints the
 * difference against what is pinned. A set generated under the wrong tokenizer is not a
 * smaller problem than a wrong constant; it is the same problem with a provenance story.
 */
import { DatabaseSync } from 'node:sqlite';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const { UNICODE61_KEEPS_CASE } = await import(process.argv[2]);

const db = new DatabaseSync(':memory:');
const setting = process.argv[3] ?? '0';
db.exec(`CREATE VIRTUAL TABLE t USING fts5(c, tokenize='unicode61 remove_diacritics ${setting}')`);
const ins = db.prepare('INSERT INTO t(rowid, c) VALUES (?, ?)');
const hit = db.prepare("SELECT count(*) AS n FROM t WHERE t MATCH ?");

/** Every cased codepoint, the same population the original sweep used. */
const cased = [];
for (let cp = 0x41; cp <= 0x1e943; cp++) {
  const c = String.fromCodePoint(cp);
  if (/\p{Lu}|\p{Lt}/u.test(c)) cased.push(c);
}

const keepsCase = new Set();
let row = 0;
db.exec('BEGIN');
for (const c of cased) {
  row++;
  ins.run(row, `a${c}b`);
}
db.exec('COMMIT');
row = 0;
for (const c of cased) {
  row++;
  const lower = c.toLowerCase();
  if (lower === c) continue; // not cased in JS either; nothing to disagree about
  // If the lowercase spelling does NOT find it, unicode61 stored something else — which for
  // this population means it kept the original case.
  let found = 0;
  try {
    found = hit.get(`"a${lower}b"`).n;
  } catch {
    found = -1;
  }
  if (found === 0) keepsCase.add(c);
}

const pinned = new Set(UNICODE61_KEEPS_CASE);
const added = [...keepsCase].filter((c) => !pinned.has(c));
const removed = [...pinned].filter((c) => !keepsCase.has(c));
const show = (xs) => xs.map((c) => `${c} U+${c.codePointAt(0).toString(16).toUpperCase().padStart(4, '0')}`).join('  ');

console.log(`swept ${cased.length} cased codepoints against remove_diacritics ${setting}`);
console.log(`pinned set: ${pinned.size}   swept set: ${keepsCase.size}`);
console.log(`\nIN THE SWEPT SET BUT NOT PINNED (${added.length}) — the query would be sent to a token the index does not hold:`);
console.log(added.length ? show(added) : '  (none)');
console.log(`\nPINNED BUT NOT IN THE SWEPT SET (${removed.length}) — kept uppercase for no reason under this tokenizer:`);
console.log(removed.length ? show(removed.slice(0, 40)) + (removed.length > 40 ? `  … and ${removed.length - 40} more` : '') : '  (none)');
